import { useState, useCallback, useRef } from 'react';

/**
 * Navigation par pile : retour étape par étape (sidebar = switch, drill-down = push).
 */
export function useViewNavigation(homeView = 'overview') {
  const homeRef = useRef(homeView);
  homeRef.current = homeView;

  const [stack, setStack] = useState([homeView]);
  const view = stack[stack.length - 1];
  const canGoBack = stack.length > 1;

  const switchView = useCallback((newView) => {
    setStack(newView === homeRef.current ? [homeRef.current] : [homeRef.current, newView]);
  }, []);

  const pushView = useCallback((newView) => {
    setStack((prev) => {
      if (prev[prev.length - 1] === newView) return prev;
      return [...prev, newView];
    });
  }, []);

  const goBack = useCallback(() => {
    let moved = false;
    setStack((prev) => {
      if (prev.length <= 1) return prev;
      moved = true;
      return prev.slice(0, -1);
    });
    return moved;
  }, []);

  const resetToHome = useCallback(() => {
    setStack([homeRef.current]);
  }, []);

  const getBackLabel = useCallback((labels = {}) => {
    if (stack.length <= 1) return 'Retour';
    const prevView = stack[stack.length - 2];
    return labels[prevView] || 'Retour';
  }, [stack]);

  return {
    view,
    stack,
    switchView,
    pushView,
    goBack,
    canGoBack,
    getBackLabel,
    resetToHome,
  };
}
