/* ─── Animated Number Counter ──────────────────────────────── */
const AnimatedCounter = ({ value, duration = 1.5 }) => {
  const [display, setDisplay] = useState(0);
  useEffect(() => {
    let start = 0;
    const end = parseInt(value, 10) || 0;
    if (start === end) { setDisplay(end); return; }
    const step = Math.ceil(end / (duration * 60));
    const timer = setInterval(() => {
      start = Math.min(start + step, end);
      setDisplay(start);
      if (start >= end) clearInterval(timer);
    }, 1000 / 60);
    return () => clearInterval(timer);
  }, [value, duration]);
  return <span>{display}</span>;
};

/* ─── Status Badge ──────────────────────────────────────────── */
const StatusBadge = ({ statut }) => {
  const cfg = {
    EN_ATTENTE: { label: 'En attente', color: '#F59E0B', bg: 'rgba(245,158,11,0.12)', icon: <Clock size={12}/> },
    ACCEPTE:    { label: 'Actif',      color: '#10B981', bg: 'rgba(16,185,129,0.12)', icon: <CheckCircle2 size={12}/> },
    REFUSE:     { label: 'Refusé',     color: '#F43F5E', bg: 'rgba(244,63,94,0.12)',  icon: <XCircle size={12}/> },
  };
  const s = cfg[statut] || cfg.EN_ATTENTE;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: '5px',
      padding: '4px 12px', borderRadius: '50px',
      background: s.bg, color: s.color,
      fontSize: '0.75rem', fontWeight: '700', letterSpacing: '0.5px'
    }}>
      {s.icon} {s.label}
    </span>
  );
};

/* ─── Glassmorphism Card ────────────────────────────────────── */
const GlassCard = ({ children, style = {}, onClick, hover = true }) => (
  <motion.div
    onClick={onClick}
    whileHover={hover ? { y: -3, boxShadow: '0 16px 48px rgba(0,0,0,0.4)' } : {}}
    transition={{ type: 'spring', stiffness: 400, damping: 25 }}
    style={{
      background: '#f8fafc',
      backdropFilter: 'blur(20px)',
      border: '1px solid #e2e8f0',
      borderRadius: '16px',
      padding: '1.25rem',
      cursor: onClick ? 'pointer' : 'default',
      ...style
    }}
  >
    {children}
  </motion.div>
);

/* ─── Floating Orbs Background ─────────────────────────────── */
const FloatingOrbs = () => (
  <div style={{ position: 'fixed', inset: 0, overflow: 'hidden', pointerEvents: 'none', zIndex: 0 }}>
    {[
      { x: '10%', y: '20%', color: '#10B98130', size: 500, delay: 0 },
      { x: '80%', y: '60%', color: '#38BDF820', size: 400, delay: 3 },
      { x: '50%', y: '80%', color: '#8B5CF620', size: 350, delay: 6 },
    ].map((orb, i) => (
      <motion.div
        key={i}
        animate={{ scale: [1, 1.15, 1], opacity: [0.5, 0.8, 0.5] }}
        transition={{ duration: 8 + i * 2, repeat: Infinity, delay: orb.delay, ease: 'easeInOut' }}
        style={{
          position: 'absolute', left: orb.x, top: orb.y,
          width: orb.size, height: orb.size,
          borderRadius: '50%',
          background: `radial-gradient(circle, ${orb.color} 0%, transparent 70%)`,
          transform: 'translate(-50%, -50%)'
        }}
      />
    ))}
  </div>
);

/* ─── Stat Card ─────────────────────────────────────────────── */
const StatCard = ({ icon, value, label, color, bg, delay = 0 }) => (
  <motion.div
    initial={{ opacity: 0, y: 30, scale: 0.95 }}
    animate={{ opacity: 1, y: 0, scale: 1 }}
    transition={{ delay, type: 'spring', stiffness: 200, damping: 20 }}
  >
    <GlassCard style={{ display: 'flex', alignItems: 'center', gap: '0.9rem', padding: '1rem' }}>
      <motion.div
        whileHover={{ rotate: 10, scale: 1.1 }}
        style={{
          width: 44, height: 44, borderRadius: '12px',
          background: bg, display: 'flex', alignItems: 'center', justifyContent: 'center',
          flexShrink: 0
        }}
      >
        {React.cloneElement(icon, { color, size: 20 })}
      </motion.div>
      <div style={{ minWidth: 0 }}>
        <div style={{ fontSize: '1.6rem', fontWeight: '800', color: 'white', lineHeight: 1 }}>
          <AnimatedCounter value={value} />
        </div>
        <div style={{ color: '#475569', fontSize: '0.75rem', marginTop: '3px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{label}</div>
      </div>
    </GlassCard>
  </motion.div>
);

/* ─── Child Card ────────────────────────────────────────────── */
const ChildCard = ({ child, onViewStats, index }) => (
  <motion.div
    initial={{ opacity: 0, y: 30 }}
    animate={{ opacity: 1, y: 0 }}
    transition={{ delay: index * 0.08, type: 'spring', stiffness: 200, damping: 22 }}
  >
    <GlassCard onClick={child.statut === 'ACCEPTE' ? () => onViewStats(child.etudiantId) : undefined}
      style={{ position: 'relative', overflow: 'hidden' }}
    >
      {/* Top accent line */}
      <div style={{
        position: 'absolute', top: 0, left: 0, right: 0, height: '3px',
        background: child.statut === 'ACCEPTE'
          ? 'linear-gradient(90deg, #10B981, #38BDF8)'
          : child.statut === 'REFUSE'
            ? 'linear-gradient(90deg, #F43F5E, #FB7185)'
            : 'linear-gradient(90deg, #F59E0B, #FCD34D)'
      }}/>

      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: '1rem' }}>
        <div style={{
          width: 48, height: 48, borderRadius: '14px',
          background: 'linear-gradient(135deg, #10B981, #0D9488)',
          display: 'flex', alignItems: 'center', justifyContent: 'center',
          fontSize: '1.3rem', fontWeight: '800', color: 'white'
        }}>
          {(child.nomComplet || '?').charAt(0).toUpperCase()}
        </div>
        <StatusBadge statut={child.statut} />
      </div>

      <h3 style={{ color: 'white', fontWeight: '700', fontSize: '1.05rem', marginBottom: '0.3rem' }}>
        {child.nomComplet}
      </h3>
      <p style={{ color: '#475569', fontSize: '0.85rem', marginBottom: '1.2rem' }}>
        {child.filiere || 'Filière non renseignée'}
      </p>

      {child.statut === 'ACCEPTE' ? (
        <motion.div
          whileHover={{ x: 4 }}
          style={{
            display: 'flex', alignItems: 'center', gap: '8px',
            color: '#10B981', fontSize: '0.88rem', fontWeight: '600'
          }}
        >
          <Eye size={16}/> Voir les statistiques <ChevronRight size={14}/>
        </motion.div>
      ) : child.statut === 'EN_ATTENTE' ? (
        <div style={{ color: '#F59E0B', fontSize: '0.82rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
          <Clock size={14}/> En attente de confirmation de l'étudiant
        </div>
      ) : (
        <div style={{ color: '#F43F5E', fontSize: '0.82rem', display: 'flex', alignItems: 'center', gap: '6px' }}>
          <XCircle size={14}/> Demande refusée
        </div>
      )}
    </GlassCard>
  </motion.div>
);

/* ─── Notification Panel ────────────────────────────────────── */
const NotifPanel = ({ requests, onRespond, onClose }) => (
  <AnimatePresence>
    <motion.div
      initial={{ opacity: 0, y: -15, scale: 0.97 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      exit={{ opacity: 0, y: -15, scale: 0.97 }}
      transition={{ type: 'spring', stiffness: 400, damping: 30 }}
      style={{
        position: 'absolute', top: '50px', right: 0, width: 'min(340px, 92vw)',
        background: 'white', backdropFilter: 'blur(0px)',
        border: '1px solid #e2e8f0',
        borderRadius: '20px', zIndex: 200,
        boxShadow: '0 12px 40px rgba(0,0,0,0.1)', overflow: 'hidden'
      }}
    >
      <div style={{ padding: '16px 20px', borderBottom: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: '8px' }}>
          <Bell size={16} color="#38BDF8"/>
          <span style={{ fontWeight: '700', color: '#0f172a', fontSize: '0.95rem' }}>Demandes de suivi</span>
          {requests.length > 0 && (
            <span style={{ background: '#E11D48', color: 'white', borderRadius: '50px', padding: '1px 8px', fontSize: '0.72rem', fontWeight: '700' }}>
              {requests.length}
            </span>
          )}
        </div>
        <motion.button whileHover={{ rotate: 90 }} onClick={onClose} style={{ background: 'none', border: 'none', color: '#475569', cursor: 'pointer', display: 'flex', padding: '2px' }}>
          <X size={16}/>
        </motion.button>
      </div>
      <div style={{ maxHeight: '380px', overflowY: 'auto' }}>
        {requests.length === 0 ? (
          <div style={{ padding: '30px 20px', textAlign: 'center', color: '#475569' }}>
            <Bell size={32} style={{ opacity: 0.3, marginBottom: '12px' }}/>
            <p style={{ margin: 0, fontSize: '0.88rem' }}>Aucune demande en attente</p>
          </div>
        ) : requests.map((pr, i) => (
          <motion.div
            key={pr.suiviId}
            initial={{ opacity: 0, x: -10 }}
            animate={{ opacity: 1, x: 0 }}
            transition={{ delay: i * 0.06 }}
            style={{
              padding: '16px 20px',
              borderBottom: '1px solid #f1f5f9',
              background: 'rgba(56,189,248,0.04)'
            }}
          >
            <div style={{ display: 'flex', gap: '10px', marginBottom: '12px' }}>
              <div style={{
                width: 36, height: 36, borderRadius: '10px',
                background: 'linear-gradient(135deg, #38BDF8, #0EA5E9)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: 'white', fontWeight: '800', fontSize: '0.95rem', flexShrink: 0
              }}>
                {(pr.demandeurNom || '?').charAt(0)}
              </div>
              <div>
                <p style={{ margin: 0, color: 'white', fontWeight: '600', fontSize: '0.9rem' }}>{pr.demandeurNom}</p>
                <p style={{ margin: 0, color: '#475569', fontSize: '0.78rem' }}>souhaite que vous le suiviez</p>
              </div>
            </div>
            <div style={{ display: 'flex', gap: '8px' }}>
              <motion.button
                whileHover={{ scale: 1.03 }} whileTap={{ scale: 0.97 }}
                onClick={() => onRespond(pr.suiviId, true)}
                style={{ flex: 1, padding: '8px', borderRadius: '10px', border: 'none', background: 'linear-gradient(135deg, #10B981, #059669)', color: 'white', cursor: 'pointer', fontWeight: '700', fontSize: '0.82rem' }}
              >
                <CheckCircle2 size={13} style={{ verticalAlign: 'middle', marginRight: '4px' }}/> Accepter
              </motion.button>
              <motion.button
                whileHover={{ scale: 1.03 }} whileTap={{ scale: 0.97 }}
                onClick={() => onRespond(pr.suiviId, false)}
                style={{ flex: 1, padding: '8px', borderRadius: '10px', border: '1px solid rgba(244,63,94,0.4)', background: 'rgba(244,63,94,0.08)', color: '#F43F5E', cursor: 'pointer', fontWeight: '700', fontSize: '0.82rem' }}
              >
                <XCircle size={13} style={{ verticalAlign: 'middle', marginRight: '4px' }}/> Refuser
              </motion.button>
            </div>
          </motion.div>
        ))}
      </div>
    </motion.div>
  </AnimatePresence>
);

/* ─── MAIN COMPONENT ────────────────────────────────────────── */
const PARENT_VIEW_LABELS = {
  overview: 'Vue d\'ensemble',
  add: 'Suivre un enfant',
  apps: 'Suivi applications',
  stats: 'Statistiques',
};

const ParentDashboard = () => {
  const { view, switchView, pushView, goBack, canGoBack, getBackLabel, resetToHome } = useViewNavigation('overview');
  const [user, setUser] = useState(null);
  const [children, setChildren] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResult, setSearchResult] = useState(null);
  const [searching, setSearching] = useState(false);
  const [childStats, setChildStats] = useState(null);
  const [statsLoading, setStatsLoading] = useState(false);
  const [pendingRequests, setPendingRequests] = useState([]);
  const [showNotifList, setShowNotifList] = useState(false);
  const [showProfile, setShowProfile] = useState(false);
  const [showLogoutConfirm, setShowLogoutConfirm] = useState(false);
  const [requestLoading, setRequestLoading] = useState(false);
  const [toast, setToast] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [isMobile, setIsMobile] = useState(() => window.innerWidth < 768);

  useEffect(() => {
    const onResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', onResize);
    return () => window.removeEventListener('resize', onResize);
  }, []);

  const showToast = (msg, type = 'success') => {
    setToast({ msg, type });
    setTimeout(() => setToast(null), 3500);
  };

  const handleGoBack = () => {
    if (view === 'stats') setChildStats(null);
    goBack();
  };

  // Bouton RETOUR Android : modals puis navigation interne
  useEffect(() => {
    const off = pushBackHandler(() => {
      if (showLogoutConfirm) { setShowLogoutConfirm(false); return true; }
      if (showProfile) { setShowProfile(false); return true; }
      if (showNotifList) { setShowNotifList(false); return true; }
      if (canGoBack) { handleGoBack(); return true; }
      return false;
    });
    return off;
  }, [canGoBack, showLogoutConfirm, showProfile, showNotifList, view]);

  useEffect(() => { fetchData(); }, []);

  const fetchData = async (showRefresh = false) => {
    if (showRefresh) setRefreshing(true);
    else setLoading(true);
    try {
      const uRes = await authAPI.getProfile();
      setUser(uRes.data);
      const [cRes, reqRes] = await Promise.all([
        parentAPI.getMyChildren(),
        parentAPI.getPendingRequests()
      ]);
      setChildren(cRes.data || []);
      setPendingRequests(reqRes.data || []);
    } catch (err) {
      console.error('Erreur de chargement', err);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const handleRespondRequest = async (suiviId, accepter) => {
    try {
      await parentAPI.respondRequest(suiviId, accepter);
      showToast(accepter ? '✅ Demande acceptée ! Vous pouvez suivre cet enfant.' : '❌ Demande refusée.');
      setShowNotifList(false);
      fetchData(true);
    } catch (err) {
      showToast('Erreur lors de la réponse.', 'error');
    }
  };

  const activeChildren   = children.filter(c => c.statut === 'ACCEPTE');
  const pendingChildren  = children.filter(c => c.statut === 'EN_ATTENTE');

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchQuery.trim()) return;
    setSearching(true);
    setSearchResult(null);
    try {
      const res = await parentAPI.searchStudent(searchQuery);
      setSearchResult(res.data);
    } catch (err) {
      showToast('Aucun étudiant trouvé avec ces informations.', 'error');
    } finally {
      setSearching(false);
    }
  };

  const handleRequestFollow = async () => {
    if (!searchResult || requestLoading) return;
    setRequestLoading(true);
    try {
      await parentAPI.requestFollow(searchResult.id);
      showToast('📨 Demande envoyée ! L\'étudiant doit accepter.');
      setSearchResult(null);
      setSearchQuery('');
      fetchData(true);
      setTimeout(() => resetToHome(), 1500);
    } catch (err) {
      showToast(err.response?.data?.message || 'Erreur lors de la demande.', 'error');
    } finally {
      setRequestLoading(false);
    }
  };

  const loadChildStats = async (etudiantId) => {
    setStatsLoading(true);
    pushView('stats');
    try {
      const res = await parentAPI.getChildStats(etudiantId);
      setChildStats(res.data);
    } catch (err) {
      showToast('Erreur de chargement des statistiques.', 'error');
      resetToHome();
    } finally {
      setStatsLoading(false);
    }
  };

  /* ── Loading Screen ─────────────────────────────────────────── */
  if (loading) return <BrandedLoader message="Chargement du portail parental…" variant="green" />;

  const navItems = [
    { id: 'overview', icon: <LayoutDashboard size={18}/>, label: 'Vue d\'ensemble' },
    { id: 'add',      icon: <UserCheck size={18}/>,       label: 'Suivre un enfant' },
    { id: 'apps',     icon: <Smartphone size={18}/>,      label: 'Suivi apps' },
  ];

  return (
    <div style={{ display: 'flex', minHeight: '100dvh', background: '#070C18', color: 'white', position: 'relative', fontFamily: "'Inter', -apple-system, sans-serif", overflowX: 'hidden' }}>
      <FloatingOrbs />

      {/* ── OVERLAY MOBILE ────────────────────────────────────── */}
      {isMobile && sidebarOpen && (
        <div
          onClick={() => setSidebarOpen(false)}
          style={{
            position: 'fixed', inset: 0,
            background: 'rgba(0,0,0,0.65)',
            backdropFilter: 'blur(4px)',
            zIndex: 299
          }}
        />
      )}

      {/* ── SIDEBAR ───────────────────────────────────────────── */}
      <motion.aside
        initial={isMobile ? { x: -280 } : { x: -80, opacity: 0 }}
        animate={isMobile
          ? { x: sidebarOpen ? 0 : -280 }
          : { x: 0, opacity: 1 }
        }
        transition={{ type: 'spring', stiffness: 280, damping: 28 }}
        style={{
          width: isMobile ? Math.min(260, window.innerWidth * 0.82) : 260,
          flexShrink: 0,
          background: 'white',
          backdropFilter: 'blur(24px)',
          borderRight: '1px solid #e2e8f0',
          display: 'flex', flexDirection: 'column',
          position: isMobile ? 'fixed' : 'sticky',
          top: 0, left: 0,
          height: '100dvh',
          zIndex: 300,
          overflowY: 'auto',
          overscrollBehavior: 'contain',
        }}
      >
        {/* Brand + Close btn */}
        <div style={{ padding: '20px 18px 16px', borderBottom: '1px solid #e2e8f0', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
            <motion.div
              animate={{ rotate: [0, 5, -5, 0] }}
              transition={{ duration: 4, repeat: Infinity }}
              style={{ width: 38, height: 38, borderRadius: '12px', background: 'linear-gradient(135deg, #10B981, #0D9488)', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}
            >
              <ShieldCheck size={20} color="white"/>
            </motion.div>
            <div>
              <div style={{ fontWeight: '800', fontSize: '0.95rem', color: 'white', letterSpacing: '-0.3px' }}>RevisIA_H24</div>
              <div style={{ fontSize: '0.62rem', color: '#10B981', fontWeight: '700', letterSpacing: '2px', textTransform: 'uppercase' }}>Portail Parent</div>
            </div>
          </div>
          {isMobile && (
            <button
              onClick={() => setSidebarOpen(false)}
              style={{ background: '#f1f5f9', border: '1px solid #e2e8f0', color: '#475569', width: 34, height: 34, borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0 }}
            >
              <X size={16}/>
            </button>
          )}
        </div>

        {/* Nav */}
        <nav style={{ padding: '16px 12px', flex: 1 }}>
          {navItems.map((item, i) => (
            <motion.button
              key={item.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: i * 0.08 }}
              onClick={() => switchView(item.id)}
              whileHover={{ x: 4 }}
              style={{
                width: '100%', display: 'flex', alignItems: 'center', gap: '12px',
                padding: '12px 16px', borderRadius: '14px', border: 'none',
                background: view === item.id ? 'rgba(16,185,129,0.15)' : 'transparent',
                color: view === item.id ? '#10B981' : '#94A3B8',
                cursor: 'pointer', fontWeight: view === item.id ? '700' : '500',
                fontSize: '0.9rem', marginBottom: '4px',
                transition: 'all 0.2s', textAlign: 'left',
                borderLeft: view === item.id ? '3px solid #10B981' : '3px solid transparent',
              }}
            >
              {item.icon} {item.label}
              {item.id === 'overview' && activeChildren.length > 0 && (
                <span style={{ marginLeft: 'auto', background: '#10B981', color: 'white', borderRadius: '50px', padding: '1px 7px', fontSize: '0.72rem', fontWeight: '700' }}>
                  {activeChildren.length}
                </span>
              )}
            </motion.button>
          ))}
        </nav>

        {/* Code parent badge */}
        {user && (
          <motion.div
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: 0.4 }}
            style={{ margin: '0 12px 12px', padding: '14px 16px', borderRadius: '14px', background: 'rgba(16,185,129,0.08)', border: '1px solid rgba(16,185,129,0.2)' }}
          >
            <div style={{ fontSize: '0.68rem', color: '#475569', textTransform: 'uppercase', letterSpacing: '1.5px', marginBottom: '5px' }}>
              Mon Code Parent
            </div>
            <div style={{ fontSize: '1.15rem', fontWeight: '800', color: '#10B981', letterSpacing: '3px' }}>
              {user.registrationCode}
            </div>
            <div style={{ fontSize: '0.72rem', color: '#475569', marginTop: '4px' }}>
              Donnez ce code à votre enfant
            </div>
          </motion.div>
        )}

        {/* Logout */}
        <div style={{ padding: '12px', borderTop: '1px solid #f1f5f9' }}>
          <button className="btn-logout" onClick={() => setShowLogoutConfirm(true)}>
            <LogOut size={16}/> Se déconnecter
          </button>
        </div>
      </motion.aside>

      {/* ── MAIN ──────────────────────────────────────────────── */}
      <main style={{ flex: 1, overflow: 'auto', overflowX: 'hidden', position: 'relative', zIndex: 1, minWidth: 0 }}>

        {/* Header */}
        <motion.header
          initial={{ opacity: 0, y: -20 }}
          animate={{ opacity: 1, y: 0 }}
          style={{
            padding: isMobile ? '12px 16px' : '18px 28px',
            borderBottom: '1px solid #e2e8f0',
            backdropFilter: 'blur(20px)',
            background: 'rgba(7,12,24,0.9)',
            position: 'sticky', top: 0, zIndex: 50,
            display: 'flex', alignItems: 'center', justifyContent: 'space-between',
            gap: '12px'
          }}
        >
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px', minWidth: 0 }}>
            {/* Hamburger menu (mobile uniquement) */}
            {isMobile && (
              <motion.button
                whileTap={{ scale: 0.92 }}
                onClick={() => setSidebarOpen(true)}
                style={{ background: 'rgba(16,185,129,0.1)', border: '1px solid rgba(16,185,129,0.25)', color: '#10B981', width: 38, height: 38, borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', flexShrink: 0 }}
              >
                <svg width="18" height="14" viewBox="0 0 18 14" fill="none">
                  <rect y="0" width="18" height="2" rx="1" fill="currentColor"/>
                  <rect y="6" width="12" height="2" rx="1" fill="currentColor"/>
                  <rect y="12" width="18" height="2" rx="1" fill="currentColor"/>
                </svg>
              </motion.button>
            )}
            <div style={{ minWidth: 0 }}>
              <h1 style={{ margin: 0, fontSize: isMobile ? '1.1rem' : '1.45rem', fontWeight: '800', background: 'linear-gradient(135deg, #fff 30%, #10B981)', WebkitBackgroundClip: 'text', WebkitTextFillColor: 'transparent', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
                {view === 'overview' ? 'Vue d\'ensemble' : view === 'add' ? 'Suivre un enfant' : view === 'apps' ? 'Suivi apps' : 'Statistiques'}
              </h1>
              {!isMobile && (
                <p style={{ margin: 0, color: '#475569', fontSize: '0.82rem', marginTop: '2px' }}>
                  {user ? `Bonjour, ${user.nomComplet?.split(' ')[0]} 👋` : 'Portail Parental'}
                </p>
              )}
            </div>
          </div>

          <div style={{ display: 'flex', alignItems: 'center', gap: isMobile ? '8px' : '12px', flexShrink: 0 }}>
            {/* Refresh */}
            <motion.button
              whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
              onClick={() => fetchData(true)}
              style={{ background: '#f1f5f9', border: '1px solid #e2e8f0', color: '#475569', padding: '9px', borderRadius: '10px', cursor: 'pointer', display: 'flex' }}
            >
              <motion.span animate={refreshing ? { rotate: 360 } : {}} transition={{ duration: 0.8, repeat: refreshing ? Infinity : 0, ease: 'linear' }}>
                <RefreshCw size={15}/>
              </motion.span>
            </motion.button>

            {/* Bell */}
            <div style={{ position: 'relative' }}>
              <motion.button
                whileHover={{ scale: 1.05 }} whileTap={{ scale: 0.95 }}
                onClick={() => setShowNotifList(!showNotifList)}
                style={{
                  background: pendingRequests.length > 0 ? 'rgba(56,189,248,0.1)' : '#f1f5f9',
                  border: `1px solid ${pendingRequests.length > 0 ? 'rgba(56,189,248,0.3)' : 'rgba(255,255,255,0.1)'}`,
                  color: pendingRequests.length > 0 ? '#38BDF8' : '#94A3B8',
                  padding: '10px', borderRadius: '12px', cursor: 'pointer', display: 'flex', position: 'relative'
                }}
              >
                <Bell size={18}/>
                {pendingRequests.length > 0 && (
                  <motion.span
                    initial={{ scale: 0 }} animate={{ scale: 1 }}
                    style={{
                      position: 'absolute', top: '-5px', right: '-5px',
                      background: '#E11D48', color: 'white', borderRadius: '50%',
                      width: '18px', height: '18px', fontSize: '0.65rem', fontWeight: '800',
                      display: 'flex', alignItems: 'center', justifyContent: 'center'
                    }}
                  >
                    {pendingRequests.length}
                  </motion.span>
                )}
              </motion.button>
              {showNotifList && (
                <NotifPanel
                  requests={pendingRequests}
                  onRespond={handleRespondRequest}
                  onClose={() => setShowNotifList(false)}
                />
              )}
            </div>

            {/* Avatar */}
            {user && (
              <div onClick={() => setShowProfile(true)} style={{ cursor: 'pointer',
                width: 40, height: 40, borderRadius: '12px',
                background: 'linear-gradient(135deg, #10B981, #0D9488)',
                display: 'flex', alignItems: 'center', justifyContent: 'center',
                color: 'white', fontWeight: '800', fontSize: '1rem',
                overflow: 'hidden', flexShrink: 0, transition: 'opacity 0.2s' }}
                title="Mon profil"
                onMouseEnter={e => e.currentTarget.style.opacity = '0.8'}
                onMouseLeave={e => e.currentTarget.style.opacity = '1'}>
                {user.photoUrl
                  ? <img src={user.photoUrl} alt="avatar" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                  : user.nomComplet?.charAt(0)
                }
              </div>
            )}
          </div>
        </motion.header>

        {/* ── CONTENT AREA ──────────────────────────────────── */}
        <div style={{
          padding: isMobile ? '16px 14px' : '28px',
          paddingBottom: isMobile ? 'calc(72px + env(safe-area-inset-bottom, 0px))' : '28px'
        }}>
          {canGoBack && (
            <DashboardBackButton
              label={`Retour — ${getBackLabel(PARENT_VIEW_LABELS)}`}
              onBack={handleGoBack}
              style={isMobile ? { marginLeft: '-14px', marginRight: '-14px', width: 'calc(100% + 28px)' } : {}}
            />
          )}
          <AnimatePresence mode="wait">

            {/* ══ VUE OVERVIEW ══════════════════════════════════ */}
            {view === 'overview' && (
              <motion.div
                key="overview"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3 }}
              >
                {/* Stats row */}
                <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr 1fr' : 'repeat(auto-fill, minmax(200px, 1fr))', gap: isMobile ? '10px' : '1.2rem', marginBottom: isMobile ? '1.5rem' : '2.5rem' }}>
                  <StatCard delay={0}   icon={<Users/>}        value={activeChildren.length}  label="Enfants suivis actifs"  color="#10B981" bg="rgba(16,185,129,0.12)"/>
                  <StatCard delay={0.1} icon={<Clock/>}        value={pendingChildren.length} label="En attente"              color="#F59E0B" bg="rgba(245,158,11,0.12)"/>
                  <StatCard delay={0.2} icon={<Bell/>}         value={pendingRequests.length} label="Demandes reçues"          color="#38BDF8" bg="rgba(56,189,248,0.12)"/>
                  <StatCard delay={0.3} icon={<TrendingUp/>}   value={children.length}        label="Total liaison"           color="#8B5CF6" bg="rgba(139,92,246,0.12)"/>
                </div>

                {/* Children Section */}
                <motion.div
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  transition={{ delay: 0.3 }}
                  style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '1.2rem', flexWrap: 'wrap', gap: '10px' }}
                >
                  <div>
                    <h2 style={{ margin: 0, fontWeight: '700', fontSize: isMobile ? '1rem' : '1.2rem', color: 'white' }}>Mes Enfants</h2>
                    <p style={{ margin: '3px 0 0', color: '#475569', fontSize: '0.8rem' }}>{children.length} étudiant{children.length !== 1 ? 's' : ''} lié{children.length !== 1 ? 's' : ''}</p>
                  </div>
                  <motion.button
                    whileHover={{ scale: 1.03, y: -2 }} whileTap={{ scale: 0.97 }}
                    onClick={() => switchView('add')}
                    style={{
                      display: 'flex', alignItems: 'center', gap: '8px',
                      padding: isMobile ? '9px 14px' : '10px 20px', borderRadius: '12px', border: 'none',
                      background: 'linear-gradient(135deg, #10B981, #059669)',
                      color: 'white', fontWeight: '700', fontSize: '0.85rem', cursor: 'pointer'
                    }}
                  >
                    <UserCheck size={15}/> {isMobile ? '+ Enfant' : 'Ajouter un enfant'}
                  </motion.button>
                </motion.div>

                {children.length === 0 ? (
                  <motion.div
                    initial={{ opacity: 0, scale: 0.97 }}
                    animate={{ opacity: 1, scale: 1 }}
                    transition={{ delay: 0.4 }}
                  >
                    <GlassCard hover={false} style={{ textAlign: 'center', padding: '4rem 2rem' }}>
                      <motion.div
                        animate={{ y: [-5, 5, -5] }}
                        transition={{ duration: 3, repeat: Infinity }}
                        style={{ marginBottom: '20px' }}
                      >
                        <Heart size={56} color="#10B981" style={{ opacity: 0.5 }}/>
                      </motion.div>
                      <h3 style={{ color: '#E2E8F0', fontWeight: '700', marginBottom: '8px' }}>Aucun enfant suivi</h3>
                      <p style={{ color: '#475569', marginBottom: '24px', fontSize: '0.9rem', maxWidth: '340px', margin: '0 auto 24px' }}>
                        Commencez à suivre la progression académique de vos enfants en ajoutant leur profil.
                      </p>
                      <motion.button
                        whileHover={{ scale: 1.04 }} whileTap={{ scale: 0.96 }}
                        onClick={() => switchView('add')}
                        style={{ padding: '12px 28px', borderRadius: '12px', border: 'none', background: 'linear-gradient(135deg, #10B981, #059669)', color: 'white', fontWeight: '700', cursor: 'pointer', fontSize: '0.95rem' }}
                      >
                        Suivre mon premier enfant
                      </motion.button>
                    </GlassCard>
                  </motion.div>
                ) : (
                  <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr' : 'repeat(auto-fill, minmax(260px, 1fr))', gap: isMobile ? '12px' : '1.2rem' }}>
                    {children.map((c, i) => (
                      <ChildCard key={c.suiviId} child={c} onViewStats={loadChildStats} index={i} />
                    ))}
                  </div>
                )}
              </motion.div>
            )}

            {/* ══ VUE ADD CHILD ══════════════════════════════════ */}
            {view === 'add' && (
              <motion.div
                key="add"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3 }}
                style={{ maxWidth: 620, margin: '0 auto' }}
              >
                <GlassCard style={{ padding: '2.5rem' }}>
                  {/* Icon heading */}
                  <div style={{ display: 'flex', alignItems: 'center', gap: '16px', marginBottom: '2rem' }}>
                    <motion.div
                      animate={{ scale: [1, 1.05, 1] }}
                      transition={{ duration: 2, repeat: Infinity }}
                      style={{ width: 56, height: 56, borderRadius: '18px', background: 'linear-gradient(135deg, #10B981, #0D9488)', display: 'flex', alignItems: 'center', justifyContent: 'center' }}
                    >
                      <Link2 size={26} color="white"/>
                    </motion.div>
                    <div>
                      <h2 style={{ margin: 0, fontWeight: '800', fontSize: '1.3rem' }}>Suivre un enfant</h2>
                      <p style={{ margin: '3px 0 0', color: '#475569', fontSize: '0.84rem' }}>Entrez le code, WhatsApp ou matricule</p>
                    </div>
                  </div>

                  {/* Info box */}
                  <motion.div
                    initial={{ opacity: 0, x: -10 }}
                    animate={{ opacity: 1, x: 0 }}
                    transition={{ delay: 0.15 }}
                    style={{ padding: '14px 18px', borderRadius: '14px', background: 'rgba(56,189,248,0.06)', border: '1px solid rgba(56,189,248,0.15)', marginBottom: '2rem' }}
                  >
                    <div style={{ display: 'flex', gap: '10px', alignItems: 'flex-start' }}>
                      <Sparkles size={16} color="#38BDF8" style={{ marginTop: '2px', flexShrink: 0 }}/>
                      <p style={{ margin: 0, color: '#475569', fontSize: '0.85rem', lineHeight: 1.6 }}>
                        Demandez à votre enfant son <strong style={{ color: '#38BDF8' }}>Code Étudiant</strong> depuis son tableau de bord, ou utilisez son Numéro WhatsApp / matricule.
                        L'étudiant devra <strong style={{ color: 'white' }}>confirmer</strong> la demande pour activer le suivi.
                      </p>
                    </div>
                  </motion.div>

                  {/* Search form */}
                  <form onSubmit={handleSearch}>
                    <div style={{ position: 'relative', marginBottom: '1.2rem' }}>
                      <Search size={18} color="#64748B" style={{ position: 'absolute', left: '16px', top: '50%', transform: 'translateY(-50%)' }}/>
                      <input
                        type="text"
                        placeholder="Code, Numéro WhatsApp ou matricule…"
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        style={{
                          width: '100%', boxSizing: 'border-box',
                          padding: '14px 16px 14px 46px',
                          borderRadius: '14px',
                          border: '1px solid #e2e8f0',
                          background: '#f1f5f9',
                          color: '#0f172a', fontSize: '0.95rem',
                          outline: 'none',
                          transition: 'border-color 0.2s'
                        }}
                        onFocus={e => e.target.style.borderColor = '#10B981'}
                        onBlur={e => e.target.style.borderColor = 'rgba(255,255,255,0.1)'}
                      />
                    </div>
                    <motion.button
                      type="submit"
                      disabled={searching || !searchQuery.trim()}
                      whileHover={{ scale: 1.02, y: -1 }}
                      whileTap={{ scale: 0.98 }}
                      style={{
                        width: '100%', padding: '14px',
                        borderRadius: '14px', border: 'none',
                        background: searching || !searchQuery.trim()
                          ? '#f1f5f9'
                          : 'linear-gradient(135deg, #10B981, #059669)',
                        color: searching || !searchQuery.trim() ? '#64748B' : 'white',
                        fontWeight: '700', fontSize: '0.95rem', cursor: searching ? 'wait' : 'pointer',
                        display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px'
                      }}
                    >
                      {searching ? (
                        <>
                          <motion.span animate={{ rotate: 360 }} transition={{ duration: 0.8, repeat: Infinity, ease: 'linear' }}>
                            <RefreshCw size={16}/>
                          </motion.span>
                          Recherche en cours…
                        </>
                      ) : (
                        <><Search size={16}/> Rechercher l'étudiant</>
                      )}
                    </motion.button>
                  </form>

                  {/* Search result */}
                  <AnimatePresence>
                    {searchResult && (
                      <motion.div
                        initial={{ opacity: 0, y: 20, scale: 0.97 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 20, scale: 0.97 }}
                        transition={{ type: 'spring', stiffness: 300, damping: 25 }}
                        style={{ marginTop: '1.5rem', padding: '1.5rem', background: 'rgba(16,185,129,0.07)', borderRadius: '16px', border: '1px solid rgba(16,185,129,0.2)' }}
                      >
                        <div style={{ display: 'flex', gap: '14px', alignItems: 'center', marginBottom: '1.2rem' }}>
                          <div style={{
                            width: 52, height: 52, borderRadius: '16px',
                            background: 'linear-gradient(135deg, #10B981, #0D9488)',
                            display: 'flex', alignItems: 'center', justifyContent: 'center',
                            fontSize: '1.4rem', fontWeight: '800', color: 'white', flexShrink: 0
                          }}>
                            {(searchResult.nomComplet || '?').charAt(0)}
                          </div>
                          <div>
                            <div style={{ color: 'white', fontWeight: '700', fontSize: '1.05rem' }}>{searchResult.nomComplet}</div>
                            <div style={{ color: '#10B981', fontSize: '0.82rem', fontWeight: '600' }}>{searchResult.universite}</div>
                            <div style={{ color: '#475569', fontSize: '0.82rem' }}>{searchResult.filiere} {searchResult.niveau ? '· ' + searchResult.niveau : ''}</div>
                          </div>
                        </div>
                        <motion.button
                          onClick={handleRequestFollow}
                          disabled={requestLoading}
                          whileHover={{ scale: 1.02 }} whileTap={{ scale: 0.98 }}
                          style={{
                            width: '100%', padding: '13px',
                            borderRadius: '12px', border: 'none',
                            background: requestLoading ? '#f1f5f9' : 'linear-gradient(135deg, #10B981, #059669)',
                            color: requestLoading ? '#64748B' : 'white',
                            fontWeight: '700', fontSize: '0.95rem', cursor: requestLoading ? 'wait' : 'pointer',
                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px'
                          }}
                        >
                          {requestLoading ? (
                            <><motion.span animate={{ rotate: 360 }} transition={{ duration: 0.8, repeat: Infinity, ease: 'linear' }}><RefreshCw size={16}/></motion.span> Envoi…</>
                          ) : (
                            <><Heart size={16}/> Envoyer la demande de suivi</>
                          )}
                        </motion.button>
                      </motion.div>
                    )}
                  </AnimatePresence>
                </GlassCard>
              </motion.div>
            )}

            {/* ══ VUE SUIVI APPS ═════════════════════════════════ */}
            {view === 'apps' && (
              <motion.div
                key="apps"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3 }}
              >
                <GlassCard hover={false} style={{ padding: '2rem' }}>
                  <SuiviAppsParental mode="parent" />
                </GlassCard>
              </motion.div>
            )}

            {/* ══ VUE STATS ══════════════════════════════════════ */}
            {view === 'stats' && (
              <motion.div
                key="stats"
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                transition={{ duration: 0.3 }}
              >
                <motion.button
                  onClick={handleGoBack}
                  whileHover={{ x: -4 }}
                  style={{ display: 'flex', alignItems: 'center', gap: '8px', background: '#f1f5f9', border: '1px solid #e2e8f0', color: '#475569', padding: '10px 18px', borderRadius: '12px', cursor: 'pointer', fontWeight: '600', fontSize: '0.88rem', marginBottom: '2rem' }}
                >
                  <ArrowLeft size={16}/> Retour
                </motion.button>

                {statsLoading ? (
                  <div style={{ textAlign: 'center', padding: '4rem' }}>
                    <motion.div
                      animate={{ rotate: 360 }}
                      transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
                      style={{ width: 40, height: 40, borderRadius: '50%', border: '3px solid rgba(16,185,129,0.15)', borderTopColor: '#10B981', margin: '0 auto 16px' }}
                    />
                    <p style={{ color: '#475569' }}>Chargement des statistiques…</p>
                  </div>
                ) : childStats ? (
                  <>
                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} style={{ marginBottom: '2rem' }}>
                      <h2 style={{ margin: 0, fontWeight: '800', fontSize: '1.4rem' }}>
                        Statistiques de <span style={{ color: '#10B981' }}>{childStats.nomComplet}</span>
                      </h2>
                    </motion.div>

                    <div style={{ display: 'grid', gridTemplateColumns: isMobile ? '1fr 1fr' : 'repeat(auto-fill, minmax(200px, 1fr))', gap: isMobile ? '10px' : '1.2rem', marginBottom: isMobile ? '1.5rem' : '2.5rem' }}>
                      <StatCard delay={0}   icon={<Clock/>}     value={childStats.tempsEstimeEtudeMinutes} label="Minutes d'étude estimées" color="#10B981" bg="rgba(16,185,129,0.12)"/>
                      <StatCard delay={0.1} icon={<Zap/>}       value={childStats.actions?.length || 0}    label="Actions enregistrées"    color="#38BDF8" bg="rgba(56,189,248,0.12)"/>
                      <StatCard delay={0.2} icon={<BookOpen/>}  value={Math.round((childStats.tempsEstimeEtudeMinutes || 0) / 60 * 10) / 10} label="Heures de travail"     color="#8B5CF6" bg="rgba(139,92,246,0.12)"/>
                    </div>

                    {childStats.derniereConnexion && (
                      <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ delay: 0.3 }}>
                        <GlassCard style={{ display: 'flex', alignItems: 'center', gap: '14px', marginBottom: '2rem', padding: '1.2rem 1.75rem' }}>
                          <Activity size={20} color="#38BDF8"/>
                          <span style={{ color: '#475569', fontSize: '0.9rem' }}>
                            Dernière activité : <strong style={{ color: 'white' }}>
                              {new Date(childStats.derniereConnexion).toLocaleString('fr-FR', { dateStyle: 'long', timeStyle: 'short' })}
                            </strong>
                          </span>
                        </GlassCard>
                      </motion.div>
                    )}

                    <motion.div initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: 0.4 }}>
                      <h3 style={{ fontWeight: '700', marginBottom: '1rem', fontSize: '1.1rem' }}>Activités récentes</h3>
                      <GlassCard hover={false} style={{ padding: 0, overflow: 'hidden' }}>
                        {childStats.actions && childStats.actions.length > 0 ? (
                          <div style={{ overflowX: 'auto', WebkitOverflowScrolling: 'touch' }}>
                            <table style={{ width: '100%', borderCollapse: 'collapse' }}>
                              <thead>
                                <tr style={{ borderBottom: '1px solid #e2e8f0' }}>
                                  {['Date & Heure', 'Action', 'Détails'].map(h => (
                                    <th key={h} style={{ padding: '14px 20px', textAlign: 'left', color: '#475569', fontSize: '0.78rem', fontWeight: '700', textTransform: 'uppercase', letterSpacing: '0.8px' }}>{h}</th>
                                  ))}
                                </tr>
                              </thead>
                              <tbody>
                                {childStats.actions.map((act, idx) => (
                                  <motion.tr
                                    key={idx}
                                    initial={{ opacity: 0, x: -10 }}
                                    animate={{ opacity: 1, x: 0 }}
                                    transition={{ delay: idx * 0.04 }}
                                    style={{ borderBottom: '1px solid #f8fafc' }}
                                  >
                                    <td style={{ padding: '13px 20px', color: '#475569', fontSize: '0.85rem', whiteSpace: 'nowrap' }}>
                                      <Calendar size={13} style={{ verticalAlign: 'middle', marginRight: '6px', opacity: 0.6 }}/>
                                      {new Date(act.date).toLocaleString('fr-FR', { dateStyle: 'short', timeStyle: 'short' })}
                                    </td>
                                    <td style={{ padding: '13px 20px', color: 'white', fontWeight: '600', fontSize: '0.88rem' }}>
                                      <span style={{ background: 'rgba(16,185,129,0.1)', color: '#10B981', padding: '3px 10px', borderRadius: '6px', fontSize: '0.78rem' }}>
                                        {act.action}
                                      </span>
                                    </td>
                                    <td style={{ padding: '13px 20px', color: '#475569', fontSize: '0.85rem' }}>{act.details}</td>
                                  </motion.tr>
                                ))}
                              </tbody>
                            </table>
                          </div>
                        ) : (
                          <div style={{ padding: '3rem', textAlign: 'center', color: '#475569' }}>
                            <Activity size={36} style={{ opacity: 0.3, marginBottom: '12px' }}/>
                            <p style={{ margin: 0, fontSize: '0.9rem' }}>Aucune activité récente enregistrée.</p>
                          </div>
                        )}
                      </GlassCard>
                    </motion.div>
                  </>
                ) : null}
              </motion.div>
            )}

          </AnimatePresence>
        </div>
      </main>

      {/* ── BOTTOM NAV (mobile uniquement) ───────────────────── */}
      {isMobile && (
        <div style={{
          position: 'fixed', bottom: 0, left: 0, right: 0,
          background: 'white',
          backdropFilter: 'blur(20px)',
          borderTop: '1px solid #e2e8f0',
          display: 'flex',
          zIndex: 200,
          paddingBottom: 'env(safe-area-inset-bottom, 0px)'
        }}>
          {navItems.map(item => (
            <button
              key={item.id}
              onClick={() => switchView(item.id)}
              style={{
                flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center',
                justifyContent: 'center', padding: '8px 4px', minHeight: '56px',
                color: view === item.id ? '#10B981' : '#475569',
                background: 'none', border: 'none', cursor: 'pointer',
                fontSize: '0.65rem', fontWeight: view === item.id ? '700' : '500',
                gap: '3px', WebkitTapHighlightColor: 'transparent',
                transition: 'color 0.2s'
              }}
            >
              <div style={{ transform: view === item.id ? 'scale(1.12)' : 'scale(1)', transition: 'transform 0.2s' }}>
                {item.icon}
              </div>
              {item.label}
            </button>
          ))}
          {/* Bouton IA */}
          <button
            onClick={() => setShowProfile(true)}
            style={{
              flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center',
              justifyContent: 'center', padding: '8px 4px', minHeight: '56px',
              color: '#475569', background: 'none', border: 'none', cursor: 'pointer',
              fontSize: '0.65rem', fontWeight: '500', gap: '3px',
              WebkitTapHighlightColor: 'transparent'
            }}
          >
            <div style={{ width: 24, height: 24, borderRadius: '50%', background: 'linear-gradient(135deg, #10B981, #0D9488)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white', fontWeight: '800', fontSize: '0.75rem' }}>
              {user?.nomComplet?.charAt(0) || '?'}
            </div>
            Profil
          </button>
        </div>
      )}

      {/* ── TOAST ─────────────────────────────────────────────── */}
      <AnimatePresence>
        {toast && (
          <motion.div
            initial={{ opacity: 0, y: 60, scale: 0.95 }}
            animate={{ opacity: 1, y: 0, scale: 1 }}
            exit={{ opacity: 0, y: 60, scale: 0.95 }}
            transition={{ type: 'spring', stiffness: 400, damping: 30 }}
            style={{
              position: 'fixed',
              bottom: isMobile ? 'calc(72px + env(safe-area-inset-bottom, 0px))' : '30px',
              left: '50%', transform: 'translateX(-50%)',
              zIndex: 9999, padding: '12px 20px',
              borderRadius: '12px',
              background: toast.type === 'error' ? 'rgba(244,63,94,0.15)' : 'rgba(16,185,129,0.15)',
              backdropFilter: 'blur(20px)',
              border: `1px solid ${toast.type === 'error' ? 'rgba(244,63,94,0.3)' : 'rgba(16,185,129,0.3)'}`,
              color: toast.type === 'error' ? '#F43F5E' : '#10B981',
              fontWeight: '600', fontSize: isMobile ? '0.85rem' : '0.92rem',
              boxShadow: '0 10px 40px rgba(0,0,0,0.4)',
              maxWidth: 'calc(100vw - 40px)', textAlign: 'center'
            }}
          >
            {toast.msg}
          </motion.div>
        )}
      </AnimatePresence>
      <ParentAIAssistant children={children} />
      <AnimatePresence>
        {showProfile && user && (
          <ProfileModal user={user} onClose={() => setShowProfile(false)}
            onSaved={(u) => setUser(p => ({ ...p, ...u }))} />
        )}
      </AnimatePresence>
      <AssistanceWidget universiteId={user?.universite?.id} />
      <LogoutConfirmModal isOpen={showLogoutConfirm} onClose={() => setShowLogoutConfirm(false)} />
    </div>
  );
};

export default ParentDashboard;

