import React, { useState, useRef, useEffect } from 'react';
import { Sparkles, X, Send, Loader, Heart } from 'lucide-react';
import { motion, AnimatePresence } from 'framer-motion';
import { aiAPI, parentAPI } from '../services/api';

/**
 * Assistant IA spécialisé pour les PARENTS.
 * Le parent peut poser des questions uniquement sur les enfants qu'il suit.
 * Le contexte (filière, niveau, dernière connexion, temps d'étude, activités)
 * est chargé puis transmis à l'IA pour des réponses pertinentes.
 *
 * Usage : <ParentAIAssistant children={children} />
 */
const ParentAIAssistant = ({ children = [] }) => {
  const [open, setOpen] = useState(false);
  const [input, setInput] = useState('');
  const [loading, setLoading] = useState(false);
  const [contextReady, setContextReady] = useState(false);
  const [contexte, setContexte] = useState('');
  const [messages, setMessages] = useState([]);
  const endRef = useRef(null);

  const activeChildren = (children || []).filter(c => c.statut === 'ACCEPTE');

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Construit le contexte enfants (avec stats) à l'ouverture
  const buildContext = async () => {
    if (activeChildren.length === 0) {
      setContexte('');
      setMessages([{
        role: 'ai',
        text: "👋 Bonjour ! Vous ne suivez encore aucun enfant. Ajoutez un enfant depuis « Suivre un enfant » pour que je puisse répondre à vos questions sur son suivi."
      }]);
      setContextReady(true);
      return;
    }

    let ctx = "Tu es l'assistant parental de RevisIA_H24. Tu aides un parent à suivre la scolarité "
            + "de ses enfants. Voici les enfants que ce parent suit :\n\n";

    for (const c of activeChildren) {
      ctx += `• ${c.nomComplet} — Filière : ${c.filiere || 'non renseignée'}`;
      if (c.niveau) ctx += `, Niveau : ${c.niveau}`;
      ctx += "\n";
      try {
        const res = await parentAPI.getChildStats(c.etudiantId);
        const s = res.data || {};
        const minutes = s.tempsEstimeEtudeMinutes || 0;
        const heures = Math.floor(minutes / 60);
        const reste = minutes % 60;
        ctx += `   - Dernière connexion : ${s.derniereConnexion || 'inconnue'}\n`;
        ctx += `   - Temps d'étude estimé : ${heures}h${reste.toString().padStart(2, '0')}\n`;
        ctx += `   - Activités récentes : ${s.actions?.length || 0} action(s)\n`;
        if (Array.isArray(s.actions) && s.actions.length > 0) {
          const dernieres = s.actions.slice(0, 5)
            .map(a => (typeof a === 'string' ? a : (a.description || a.action || JSON.stringify(a))))
            .join('; ');
          ctx += `   - Détail : ${dernieres}\n`;
        }
      } catch (e) {
        ctx += `   - (statistiques indisponibles pour le moment)\n`;
      }
      ctx += "\n";
    }

    ctx += "\nRÈGLES IMPORTANTES :\n"
        +  "- Réponds UNIQUEMENT aux questions concernant le suivi de CES enfants.\n"
        +  "- Ne donne JAMAIS d'informations sur d'autres étudiants.\n"
        +  "- Sois bienveillant, rassurant et donne des conseils pratiques aux parents.\n"
        +  "- Réponds toujours en français.";

    setContexte(ctx);
    setContextReady(true);

    const noms = activeChildren.map(c => c.nomComplet).join(', ');
    setMessages([{
      role: 'ai',
      text: `👋 Bonjour ! Je suis votre assistant de suivi parental. Vous suivez : **${noms}**.\n\n`
          + `Posez-moi vos questions, par exemple :\n`
          + `• « Comment se passe la scolarité de mon enfant ? »\n`
          + `• « Est-ce qu'il étudie régulièrement ? »\n`
          + `• « Quelle est sa filière et son niveau ? »\n`
          + `• « Quels conseils pour l'aider à réussir ? »`
    }]);
  };

  const handleOpen = async () => {
    setOpen(true);
    if (!contextReady) {
      setLoading(true);
      await buildContext();
      setLoading(false);
    }
  };

  const handleSend = async (e) => {
    e?.preventDefault();
    const question = input.trim();
    if (!question || loading) return;

    setMessages(prev => [...prev, { role: 'user', text: question }]);
    setInput('');
    setLoading(true);

    try {
      // On préfixe la question avec le contexte enfants
      const res = await aiAPI.ask(question, contexte || 'Parent suivant ses enfants');
      const answer = res.data?.answer || res.data?.text
        || (typeof res.data === 'string' ? res.data : "Je n'ai pas pu générer de réponse.");
      setMessages(prev => [...prev, { role: 'ai', text: answer }]);
    } catch (err) {
      setMessages(prev => [...prev, {
        role: 'ai',
        text: "❌ Erreur : " + (err.response?.data?.error || err.message)
      }]);
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      {/* Bouton flottant */}
      {!open && (
        <motion.button
          initial={{ scale: 0, opacity: 0 }}
          animate={{ scale: 1, opacity: 1 }}
          whileHover={{ scale: 1.08 }}
          whileTap={{ scale: 0.95 }}
          onClick={handleOpen}
          title="Assistant de suivi parental"
          style={{
            position: 'fixed',
            bottom: window.innerWidth < 768 ? 'calc(64px + env(safe-area-inset-bottom, 0px))' : '28px',
            right: '18px', zIndex: 9998,
            width: '56px', height: '56px', borderRadius: '50%', border: 'none',
            cursor: 'pointer',
            background: 'linear-gradient(135deg, #10B981, #0D9488)',
            boxShadow: '0 8px 30px rgba(16, 185, 129, 0.5)',
            display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white'
          }}
        >
          <Heart size={26} />
          <span style={{
            position: 'absolute', top: '6px', right: '6px',
            width: '12px', height: '12px', borderRadius: '50%',
            background: '#38BDF8', border: '2px solid white'
          }} />
        </motion.button>
      )}

      {/* Fenêtre de chat */}
      <AnimatePresence>
        {open && (
          <motion.div
            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
            onClick={() => setOpen(false)}
            style={{
              position: 'fixed', inset: 0, zIndex: 9999,
              background: 'rgba(2, 6, 23, 0.7)', backdropFilter: 'blur(6px)',
              display: 'flex',
              alignItems: window.innerWidth < 640 ? 'flex-end' : 'flex-end',
              justifyContent: window.innerWidth < 640 ? 'center' : 'flex-end',
              padding: window.innerWidth < 640 ? '0' : '20px'
            }}
          >
            <motion.div
              initial={{ scale: 0.9, y: 30, opacity: 0 }}
              animate={{ scale: 1, y: 0, opacity: 1 }}
              exit={{ scale: 0.9, y: 30, opacity: 0 }}
              transition={{ type: 'spring', damping: 24, stiffness: 280 }}
              onClick={(e) => e.stopPropagation()}
              style={{
                width: window.innerWidth < 640 ? '100%' : '440px',
                maxWidth: window.innerWidth < 640 ? '100%' : '440px',
                height: window.innerWidth < 640 ? '88dvh' : '80vh',
                maxHeight: window.innerWidth < 640 ? '88dvh' : '640px',
                background: 'white',
                borderRadius: window.innerWidth < 640 ? '20px 20px 0 0' : '20px',
                border: '1px solid rgba(16, 185, 129, 0.3)',
                boxShadow: '0 -8px 48px rgba(0,0,0,0.1)',
                display: 'flex', flexDirection: 'column', overflow: 'hidden',
                paddingBottom: window.innerWidth < 640 ? 'env(safe-area-inset-bottom, 0px)' : '0'
              }}
            >
              {/* En-tête */}
              <div style={{
                padding: '16px 20px', borderBottom: '1px solid #e2e8f0',
                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                background: 'linear-gradient(135deg, rgba(16,185,129,0.15), rgba(13,148,136,0.1))'
              }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                  <div style={{
                    width: '40px', height: '40px', borderRadius: '12px',
                    background: 'linear-gradient(135deg, #10B981, #0D9488)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'white'
                  }}>
                    <Sparkles size={20} />
                  </div>
                  <div>
                    <p style={{ margin: 0, fontWeight: '800', color: '#0f172a', fontSize: '0.95rem' }}>
                      Assistant Suivi Parental
                    </p>
                    <p style={{ margin: 0, fontSize: '0.72rem', color: '#10B981' }}>
                      {activeChildren.length} enfant(s) suivi(s)
                    </p>
                  </div>
                </div>
                <button onClick={() => setOpen(false)}
                  style={{ background: 'rgba(239,68,68,0.15)', color: '#EF4444', border: 'none',
                           borderRadius: '50%', width: '34px', height: '34px', cursor: 'pointer',
                           display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                  <X size={18} />
                </button>
              </div>

              {/* Messages */}
              <div style={{ flex: 1, overflowY: 'auto', padding: '18px', display: 'flex', flexDirection: 'column', gap: '12px' }}>
                {messages.map((m, i) => (
                  <div key={i} style={{
                    alignSelf: m.role === 'user' ? 'flex-end' : 'flex-start',
                    maxWidth: '85%',
                    background: m.role === 'user'
                      ? 'linear-gradient(135deg, #10B981, #0D9488)'
                      : '#f0fdf4',
                    color: m.role === 'user' ? 'white' : '#0f172a',
                    padding: '10px 14px', borderRadius: '14px',
                    fontSize: '0.88rem', lineHeight: '1.5', whiteSpace: 'pre-wrap'
                  }}>
                    {m.text}
                  </div>
                ))}
                {loading && (
                  <div style={{ alignSelf: 'flex-start', color: '#10B981', display: 'flex', alignItems: 'center', gap: '8px' }}>
                    <Loader size={18} className="spinner" style={{ animation: 'spin 1s linear infinite' }} />
                    <span style={{ fontSize: '0.82rem' }}>Analyse du suivi…</span>
                  </div>
                )}
                <div ref={endRef} />
              </div>

              {/* Saisie */}
              <form onSubmit={handleSend} style={{
                padding: '14px', borderTop: '1px solid #e2e8f0',
                display: 'flex', gap: '8px'
              }}>
                <input
                  value={input}
                  onChange={(e) => setInput(e.target.value)}
                  placeholder="Posez une question sur votre enfant…"
                  disabled={loading || !contextReady}
                  style={{
                    flex: 1, padding: '12px 14px', borderRadius: '12px',
                    border: '1.5px solid #e2e8f0',
                    background: '#f8fafc', color: '#0f172a', fontSize: '0.9rem', outline: 'none'
                  }}
                />
                <button type="submit" disabled={loading || !input.trim()}
                  style={{
                    width: '46px', borderRadius: '12px', border: 'none',
                    background: 'linear-gradient(135deg, #10B981, #0D9488)',
                    color: 'white', cursor: 'pointer', display: 'flex',
                    alignItems: 'center', justifyContent: 'center'
                  }}>
                  <Send size={18} />
                </button>
              </form>
            </motion.div>
          </motion.div>
        )}
      </AnimatePresence>

      <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
    </>
  );
};

export default ParentAIAssistant;
